// Unfunded synthetic fixtures generated by the official native wallet crates.
use std::str::FromStr;
use tari_common_types::seeds::{cipher_seed::CipherSeed, mnemonic::{Mnemonic, MnemonicLanguage}};
use tari_ootle_wallet_crypto::derive_ristretto_key;
use tari_utilities::{SafePassword, ByteArray};
fn hex(bytes: &[u8]) -> String { bytes.iter().map(|b| format!("{b:02x}")).collect() }
fn main() {
    let seed = CipherSeed::random();
    let mut vectors = Vec::new();
    for passphrase in ["", "synthetic seed passphrase"] {
        let password = if passphrase.is_empty() { None } else { Some(SafePassword::from_str(passphrase).unwrap()) };
        let words = seed.to_mnemonic(MnemonicLanguage::English, password).unwrap();
        // Round-trip using exactly the official daemon/CLI mnemonic decoder.
        let password = if passphrase.is_empty() { None } else { Some(SafePassword::from_str(passphrase).unwrap()) };
        let restored = CipherSeed::from_mnemonic(&words, password).unwrap();
        for index in [0u64, 7] {
            vectors.push(serde_json::json!({"phrase":words.join(" ").reveal(),"seedPassphrase":passphrase,"accountIndex":index,
                "owner":hex(derive_ristretto_key(restored.entropy(), b"account", index).as_bytes()),
                "view":hex(derive_ristretto_key(restored.entropy(), b"view_only_key", index).as_bytes())}));
        }
    }
    std::fs::write("/workspace/hauntboard/artifacts/native-import-vectors.json", serde_json::to_vec(&vectors).unwrap()).unwrap();
    println!("Generated four unfunded official-wallet compatibility vectors.");
}

